package com.example.library;
import com.example.library.entity.*;import com.example.library.repository.*;import com.example.library.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.MediaType;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:admin_modules;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.database-platform=org.hibernate.dialect.H2Dialect","spring.jpa.hibernate.ddl-auto=create-drop","app.seed.enabled=false"}) @AutoConfigureMockMvc @Transactional
class AdminModulesIntegrationTest {
 @Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired BookRepository books;@Autowired BookCopyService inventory;@Autowired SaleRepository sales;@Autowired BookCopyRepository copies;@Autowired LibraryContentRepository contents;@Autowired com.fasterxml.jackson.databind.ObjectMapper json;
 Book book(){var b=books.save(Book.builder().title("Sale test").totalQuantity(3).availableQuantity(3).rentalPrice(BigDecimal.valueOf(5000)).salePrice(BigDecimal.valueOf(60000)).status(BookStatus.AVAILABLE).build());inventory.initialize(b.getId());return b;}
 String counter(Long id,int qty,boolean paid){return "{\"buyerEmail\":\"buyer@test.com\",\"paymentCollected\":"+paid+",\"order\":{\"items\":[{\"bookId\":"+id+",\"quantity\":"+qty+"}]}}";}
 @BeforeEach void user(){users.save(User.builder().email("buyer@test.com").fullName("Buyer").password("not-public").build());}
 @Test @WithMockUser(roles="ADMIN") void counterSaleUsesBuyerServerPricesAndPhysicalCopies()throws Exception{var b=book();mvc.perform(post("/api/v1/sales/counter").contentType(MediaType.APPLICATION_JSON).content(counter(b.getId(),2,true))).andExpect(status().isOk()).andExpect(jsonPath("$.user.email").value("buyer@test.com")).andExpect(jsonPath("$.user.password").doesNotExist()).andExpect(jsonPath("$.totalAmount").value(120000)).andExpect(jsonPath("$.items.length()").value(2));assertEquals(1,copies.countByBookIdAndStatus(b.getId(),BookCopyStatus.AVAILABLE));assertEquals(2,copies.countByBookIdAndStatus(b.getId(),BookCopyStatus.SOLD));assertEquals(1,sales.count());}
 @Test @WithMockUser(roles="ADMIN") void unpaidOrExcessStockDoesNotCreateSale()throws Exception{var b=book();mvc.perform(post("/api/v1/sales/counter").contentType(MediaType.APPLICATION_JSON).content(counter(b.getId(),1,false))).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/sales/counter").contentType(MediaType.APPLICATION_JSON).content(counter(b.getId(),4,true))).andExpect(status().isConflict());assertEquals(0,sales.count());assertEquals(3,copies.countByBookIdAndStatus(b.getId(),BookCopyStatus.AVAILABLE));}
 @Test @WithMockUser(roles="USER") void readerCannotPostCounterOrLegacySale()throws Exception{mvc.perform(post("/api/v1/sales/counter").contentType(MediaType.APPLICATION_JSON).content(counter(1L,1,true))).andExpect(status().isForbidden());mvc.perform(post("/api/v1/sales").contentType(MediaType.APPLICATION_JSON).content("{\"items\":[{\"bookId\":1,\"quantity\":1}]}")).andExpect(status().isForbidden());}
 @Test @WithMockUser(roles="ADMIN") void menuSupportsNewRoutesAndRequiresInternalDestination()throws Exception{mvc.perform(post("/api/v1/content/manage/MENU").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Read\",\"slug\":\"read-menu\",\"link\":\"/library\",\"published\":true}")).andExpect(status().isOk());for(String link:java.util.List.of("//evil.example","/api/v1/auth/login","javascript:alert(1)","")){mvc.perform(post("/api/v1/content/manage/MENU").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(java.util.Map.of("title","Bad","slug","bad","link",link)))).andExpect(status().isBadRequest());}}
 @Test @WithMockUser(roles="ADMIN") void publishedContentMustHaveTextAndConfigOnlyAllowsPublicKeys()throws Exception{mvc.perform(post("/api/v1/content/manage/POST").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Empty\",\"slug\":\"empty\",\"published\":true}")).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/content/manage/CONFIG").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"API\",\"slug\":\"payos-api-key\",\"body\":\"secret\"}")).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/content/manage/CONFIG").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Hours\",\"slug\":\"library-hours\",\"body\":\"8-17\",\"published\":true}")).andExpect(status().isOk());}
 @Test @WithMockUser(roles="ADMIN") void hideAndUnlinkBeforeDeletingContent()throws Exception{var page=new LibraryContent();page.setKind("PAGE");page.setTitle("Info");page.setSlug("info");page.setBody("Text");page.setPublished(true);contents.saveAndFlush(page);mvc.perform(delete("/api/v1/content/manage/PAGE/"+page.getId())).andExpect(status().isConflict());page.setPublished(false);var menu=new LibraryContent();menu.setKind("MENU");menu.setTitle("Info");menu.setSlug("menu-info");menu.setLink("/read/info");contents.saveAndFlush(menu);mvc.perform(delete("/api/v1/content/manage/PAGE/"+page.getId())).andExpect(status().isConflict());mvc.perform(delete("/api/v1/content/manage/MENU/"+menu.getId())).andExpect(status().isNoContent());mvc.perform(delete("/api/v1/content/manage/PAGE/"+page.getId())).andExpect(status().isNoContent());assertEquals(0,contents.count());}
 @Test @WithMockUser(roles="LIBRARIAN") void librarianCannotDeleteConfigOrMenu()throws Exception{mvc.perform(delete("/api/v1/content/manage/CONFIG/1")).andExpect(status().isForbidden());mvc.perform(delete("/api/v1/content/manage/MENU/1")).andExpect(status().isForbidden());}
 @Test @WithMockUser(roles="ADMIN") void ebookRequiresExistingBookAndCatalogHasOnlyShortPreview()throws Exception{var b=book();mvc.perform(post("/api/v1/content/manage/EBOOK").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Book\",\"slug\":\"online-book\",\"bookId\":999999,\"body\":\"Content\",\"published\":true}")).andExpect(status().isBadRequest());mvc.perform(post("/api/v1/content/manage/EBOOK").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(java.util.Map.of("title","Book","slug","online-book","bookId",b.getId(),"body","A".repeat(500),"published",true)))).andExpect(status().isOk());mvc.perform(get("/api/v1/content/catalog")).andExpect(jsonPath("$[0].body").value("A".repeat(220)));mvc.perform(get("/api/v1/content/read/online-book")).andExpect(jsonPath("$.body").value("A".repeat(500)));}

 @Test @WithMockUser(roles="ADMIN") void contactSettingsSaveTogetherPreserveIdsAndHideBlankContacts()throws Exception{
  var initial=new LibraryContent();initial.setKind("CONFIG");initial.setSlug("library-name");initial.setTitle("Name");initial.setBody("Old");contents.saveAndFlush(initial);
  var input=new java.util.HashMap<String,Object>();input.put("name","Thư viện Mộc");input.put("email","contact@example.com");input.put("phone","+84 (28) 1234-5678");input.put("address","Địa chỉ thư viện");input.put("hours","08:00–17:00");input.put("announcement","");input.put("announcementVisible",false);
  mvc.perform(put("/api/v1/content/settings").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isOk()).andExpect(jsonPath("$.email").value("contact@example.com"));
  assertEquals(initial.getId(),contents.findByKindOrderBySortOrderAscIdDesc("CONFIG").stream().filter(c->c.getSlug().equals("library-name")).findFirst().orElseThrow().getId());assertEquals(6,contents.count());
  input.put("email","invalid-email");input.put("name","Changed");mvc.perform(put("/api/v1/content/settings").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isBadRequest());
  mvc.perform(get("/api/v1/content/settings")).andExpect(jsonPath("$.name").value("Thư viện Mộc"));
  input.put("email","");mvc.perform(put("/api/v1/content/settings").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isOk());assertFalse(contents.findByKindOrderBySortOrderAscIdDesc("CONFIG").stream().filter(c->c.getSlug().equals("library-email")).findFirst().orElseThrow().isPublished());
 }
 @Test @WithMockUser(roles="LIBRARIAN") void contactSettingsRequireAdministrator()throws Exception{mvc.perform(get("/api/v1/content/settings")).andExpect(status().isForbidden());mvc.perform(put("/api/v1/content/settings").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Library\"}")).andExpect(status().isForbidden());}

 @Test @WithMockUser(roles="LIBRARIAN") void librarianCanManageBooksAndLoansButCannotAccessAdministrativeModules()throws Exception{
  mvc.perform(get("/api/v1/books")).andExpect(status().isOk());mvc.perform(get("/api/v1/loans")).andExpect(status().isOk());mvc.perform(get("/api/v1/content/manage/EBOOK")).andExpect(status().isOk());
  for(String path:java.util.List.of("/api/v1/admin/users","/api/v1/payments","/api/v1/sales","/api/v1/fines","/api/v1/statistics/summary","/api/v1/admin/reports/books.csv","/api/v1/content/manage/POST","/api/v1/content/manage/PAGE","/api/v1/content/manage/CONFIG","/api/v1/content/manage/MENU")){mvc.perform(get(path)).andExpect(status().isForbidden());}
  mvc.perform(post("/api/v1/sales/counter").contentType(MediaType.APPLICATION_JSON).content(counter(1L,1,true))).andExpect(status().isForbidden());mvc.perform(post("/api/v1/fines/1/mark-paid")).andExpect(status().isForbidden());
 }

 @Test @WithMockUser(username="buyer@test.com",roles="USER")
 void readerOrdersAtCounterAndAdminCanConfirmOnlyOnce() throws Exception {
  var b=book();
  var payload=json.writeValueAsString(java.util.Map.of("bookId",b.getId(),"quantity",2,"unitPrice",60000,
          "requestKey","12345678-1234-1234-1234-123456789012"));
  var create=post("/api/v1/purchase-orders").contentType(MediaType.APPLICATION_JSON).content(payload);
  var response=mvc.perform(create).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PENDING")).andReturn();
  long id=json.readTree(response.getResponse().getContentAsString()).get("id").asLong();
  mvc.perform(create).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));
  mvc.perform(get("/api/v1/purchase-orders/my")).andExpect(jsonPath("$.length()").value(1));
  assertEquals(0,sales.count());
  assertEquals(3,copies.countByBookIdAndStatus(b.getId(),BookCopyStatus.AVAILABLE));

  var confirmation=post("/api/v1/purchase-orders/"+id+"/confirm").contentType(MediaType.APPLICATION_JSON)
          .content("{\"paymentCollected\":true}");
  mvc.perform(confirmation).andExpect(status().isForbidden());
  var admin=org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user("admin@test.com").roles("ADMIN");
  mvc.perform(confirmation.with(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PAID"));
  mvc.perform(confirmation.with(admin)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("PAID"));
  assertEquals(1,sales.count());
  assertEquals(2,copies.countByBookIdAndStatus(b.getId(),BookCopyStatus.SOLD));
 }
}
